import{_ as o,l as s,o as e,c as d,v as t,p as n,x as r,d as l,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"ART 自适应基数树","description":"","frontmatter":{"title":"ART 自适应基数树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/art-adaptive-radix.md","filePath":"cs/art-adaptive-radix.md","lastUpdated":1789023840000}'),c={name:"cs/art-adaptive-radix.md"};function m(A,a,T,_,u,f){const i=s("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="art-自适应基数树" tabindex="-1">ART 自适应基数树 <a class="header-anchor" href="#art-自适应基数树" aria-label="Permalink to &quot;ART 自适应基数树&quot;">​</a></h1><div class="epigraph"><p>节点类型随扇出变：4、16、48、256；前缀压缩吃掉一元路径。查找沿真实键字节走，不先搅成哈希。</p><footer>—— 据 Leis, Kemper and Neumann, The Adaptive Radix Tree: ARTful Indexing for Main-Memory Databases, ICDE 2013 整理</footer></div><p><a href="/cs/hamt">上一课</a> 用哈希比特，丢失键序。<a href="/cs/trie">Trie</a> 固定 256 数组浪费。<a href="/cs/bplus-split">B+</a> 面向页。<a href="/cs/skip-list">跳表</a> 期望对数比较整键。本课不路径复制整课。缺口是 ART：内存数据库索引，按字节基数、节点形态自适应。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内存中有序索引：比较树 \\(\\log n\\) 次整键比较；哈希表不保序。基数树按字节 \\(O(|key|)\\)，但节点浪费。ART：Node4 存少量键字节+指针；Node16 SIMD 比较；Node48 用 256 字节索引进 48 指针；Node256 直接数组。lazy expansion 与路径压缩合并一元。缺口是<strong>用节点类型匹配实际扇出</strong>，保持字节序（从而范围扫描）。</p><p><span class="marginnote">Leis, Kemper, Neumann, <em>ICDE</em> 2013。整数键可大端字节化以保持序。本课不把论文实验表抄进来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：从根吃前缀，再按下一字节选孩子。插入：节点满则升级类型（4→16→48→256）。删除可降级。范围：有序孩子迭代。并发：乐观锁或 ROWEX 变体，本课点名不写完。</p>',8)),(e(),n(h,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E9%94%AE%E5%AD%97%E8%8A%82%22%5D%20--%3E%20N4%5B%22Node4%22%5D%0A%20%20K%20--%3E%20N16%5B%22Node16%22%5D%0A%20%20K%20--%3E%20N48%5B%22Node48%22%5D%0A%20%20K%20--%3E%20N256%5B%22Node256%22%5D%0A%20%20N4%20--%3E%20UP%5B%22%E6%BB%A1%E5%88%99%E5%8D%87%E7%BA%A7%E7%B1%BB%E5%9E%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 HAMT：ART 保序、无哈希；HAMT 持久更容易、无序。与后缀树：ART 是字典不是全部后缀索引。</p><p>字符串课序结束。下一单元概率结构：从通用散列族开始，给后面草图与过滤器提供碰撞合同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缓存：小节点密，256 节点吃一页级缓存线若干。前缀压缩使短分支不建多层。键必须能看成字节串；比较器自定义难塞进基数。</p><p>不要把 ART 写成 Transformer 词表；就是内存有序映射。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 ART 与 Bw-tree 对比写长。磁盘仍 B+。哈希族与完美散列是下一课序，不在 ART 里重讲。</p><p>后课默认：内存字节键有序索引可用 ART。碰撞概率的系统合同从通用散列讲起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ART：自适应扇出的字节基数树，保序。</li><li>节点 4/16/48/256 + 前缀压缩。</li><li>字符串结构课序结束；下一课通用散列。</li><li>出处：Leis, Kemper and Neumann, <em>ICDE</em>, 2013。</li></ul>',10))])}const x=o(c,[["render",m]]);export{N as __pageData,x as default};
